  Service s4=serviceFactory.createNew(c2,"HIVE");
  Service s5=serviceFactory.createNew(c2,"ZOOKEEPER");
  c1.addService(s1);
  c1.addService(s2);
  c1.addService(s3);
  c2.addService(s4);
  c2.addService(s5);
  s1.setDesiredState(State.INSTALLED);
  s2.setDesiredState(State.INSTALLED);
  s4.setDesiredState(State.INSTALLED);
